30	public class IntegerTupleSketchValueAggregator implements ValueAggregator<byte[], Sketch<IntegerSummary>> {
31	  public static final DataType AGGREGATED_VALUE_TYPE = DataType.BYTES;
32	
33	  // This changes a lot similar to the Bitmap aggregator
34	  private int _maxByteSize;
35	
36	  private final IntegerSummary.Mode _mode;
37	
38	  public IntegerTupleSketchValueAggregator(IntegerSummary.Mode mode) {
39	    _mode = mode;
40	  }
41	
42	  @Override
43	  public AggregationFunctionType getAggregationType() {
44	    return AggregationFunctionType.DISTINCTCOUNTTUPLESKETCH;
45	  }
46	
47	  @Override
48	  public DataType getAggregatedValueType() {
49	    return AGGREGATED_VALUE_TYPE;
50	  }
51	
52	  // Utility method to merge two sketches
53	  private Sketch<IntegerSummary> union(Sketch<IntegerSummary> a, Sketch<IntegerSummary> b) {
54	    return new Union<>(new IntegerSummarySetOperations(_mode, _mode)).union(a, b);
55	  }
56	
57	  @Override
58	  public Sketch<IntegerSummary> getInitialAggregatedValue(byte[] rawValue) {
59	    Sketch<IntegerSummary> initialValue = deserializeAggregatedValue(rawValue);
60	    _maxByteSize = Math.max(_maxByteSize, rawValue.length);
61	    return initialValue;
62	  }
63	
64	  @Override
65	  public Sketch<IntegerSummary> applyRawValue(Sketch<IntegerSummary> value, byte[] rawValue) {
66	    Sketch<IntegerSummary> right = deserializeAggregatedValue(rawValue);
67	    Sketch<IntegerSummary> result = union(value, right).compact();
68	    _maxByteSize = Math.max(_maxByteSize, result.toByteArray().length);
69	    return result;
70	  }
71	
72	  @Override
73	  public Sketch<IntegerSummary> applyAggregatedValue(Sketch<IntegerSummary> value,
