30	public class DistinctCountThetaSketchValueAggregator implements ValueAggregator<Object, Object> {
31	  public static final DataType AGGREGATED_VALUE_TYPE = DataType.BYTES;
32	
33	  private final SetOperationBuilder _setOperationBuilder;
34	
35	  // This changes a lot similar to the Bitmap aggregator
36	  private int _maxByteSize;
37	
38	  public DistinctCountThetaSketchValueAggregator() {
39	    _setOperationBuilder =
40	        Union.builder().setNominalEntries(CommonConstants.Helix.DEFAULT_THETA_SKETCH_NOMINAL_ENTRIES);
41	  }
42	
43	  @Override
44	  public AggregationFunctionType getAggregationType() {
45	    return AggregationFunctionType.DISTINCTCOUNTTHETASKETCH;
46	  }
47	
48	  @Override
49	  public DataType getAggregatedValueType() {
50	    return AGGREGATED_VALUE_TYPE;
51	  }
52	
53	  private void singleItemUpdate(Union thetaUnion, Object rawValue) {
54	    if (rawValue instanceof String) {
55	      thetaUnion.update((String) rawValue);
56	    } else if (rawValue instanceof Integer) {
57	      thetaUnion.update((Integer) rawValue);
58	    } else if (rawValue instanceof Long) {
59	      thetaUnion.update((Long) rawValue);
60	    } else if (rawValue instanceof Double) {
61	      thetaUnion.update((Double) rawValue);
62	    } else if (rawValue instanceof Float) {
63	      thetaUnion.update((Float) rawValue);
64	    } else if (rawValue instanceof Object[]) {
65	      multiItemUpdate(thetaUnion, (Object[]) rawValue);
66	    } else if (rawValue instanceof Sketch) {
67	      thetaUnion.union((Sketch) rawValue);
68	    } else if (rawValue instanceof Union) {
69	      thetaUnion.union(((Union) rawValue).getResult());
70	    } else {
71	      throw new IllegalStateException(
72	          "Unsupported data type for Theta Sketch aggregation: " + rawValue.getClass().getSimpleName());
73	    }
74	  }
75	
76	  private void multiItemUpdate(Union thetaUnion, Object[] rawValues) {
77	    if (rawValues instanceof String[]) {
78	      for (String s : (String[]) rawValues) {
79	        thetaUnion.update(s);
80	      }
81	    } else if (rawValues instanceof Integer[]) {
82	      for (Integer i : (Integer[]) rawValues) {
83	        thetaUnion.update(i);
84	      }
85	    } else if (rawValues instanceof Long[]) {
86	      for (Long l : (Long[]) rawValues) {
87	        thetaUnion.update(l);
88	      }
89	    } else if (rawValues instanceof Double[]) {
90	      for (Double d : (Double[]) rawValues) {
91	        thetaUnion.update(d);
92	      }
93	    } else if (rawValues instanceof Float[]) {
94	      for (Float f : (Float[]) rawValues) {
95	        thetaUnion.update(f);
96	      }
97	    } else {
98	      throw new IllegalStateException(
99	          "Unsupported data type for Theta Sketch aggregation: " + rawValues.getClass().getSimpleName());
100	    }
101	  }
102	
103	  @Override
104	  public Object getInitialAggregatedValue(Object rawValue) {
105	    Union thetaUnion = _setOperationBuilder.buildUnion();
106	    if (rawValue instanceof byte[]) { // Serialized Sketch
107	      byte[] bytes = (byte[]) rawValue;
108	      Sketch sketch = deserializeAggregatedValue(bytes);
109	      thetaUnion.union(sketch);
110	    } else if (rawValue instanceof byte[][]) { // Multiple Serialized Sketches
111	      byte[][] serializedSketches = (byte[][]) rawValue;
112	      for (byte[] sketchBytes : serializedSketches) {
113	        thetaUnion.union(deserializeAggregatedValue(sketchBytes));
114	      }
115	    } else {
116	      singleItemUpdate(thetaUnion, rawValue);
117	    }
118	    _maxByteSize = Math.max(_maxByteSize, thetaUnion.getCurrentBytes());
119	    return thetaUnion;
120	  }
121	
122	  private Union extractUnion(Object value) {
123	    if (value == null) {
124	      return _setOperationBuilder.buildUnion();
125	    } else if (value instanceof Union) {
126	      return (Union) value;
127	    } else if (value instanceof Sketch) {
128	      Sketch sketch = (Sketch) value;
129	      Union thetaUnion = _setOperationBuilder.buildUnion();
130	      thetaUnion.union(sketch);
131	      return thetaUnion;
132	    } else {
133	      throw new IllegalStateException(
134	          "Unsupported data type for Theta Sketch aggregation: " + value.getClass().getSimpleName());
135	    }
136	  }
137	
138	  @Override
139	  public Object applyRawValue(Object aggregatedValue, Object rawValue) {
140	    Union thetaUnion = extractUnion(aggregatedValue);
141	    if (rawValue instanceof byte[]) {
142	      Sketch sketch = deserializeAggregatedValue((byte[]) rawValue);
143	      thetaUnion.union(sketch);
144	    } else {
145	      singleItemUpdate(thetaUnion, rawValue);
146	    }
147	    _maxByteSize = Math.max(_maxByteSize, thetaUnion.getCurrentBytes());
148	    return thetaUnion;
149	  }
150	
151	  @Override
152	  public Object applyAggregatedValue(Object value, Object aggregatedValue) {
153	    Union thetaUnion = extractUnion(aggregatedValue);
154	    singleItemUpdate(thetaUnion, value);
155	    _maxByteSize = Math.max(_maxByteSize, thetaUnion.getCurrentBytes());
156	    return thetaUnion;
157	  }
158	
159	  @Override
160	  public Object cloneAggregatedValue(Object value) {
161	    return deserializeAggregatedValue(serializeAggregatedValue(value));
162	  }
163	
164	  @Override
165	  public int getMaxAggregatedValueByteSize() {
166	    return _maxByteSize;
167	  }
168	
169	  @Override
170	  public byte[] serializeAggregatedValue(Object value) {
171	    if (value instanceof Union) {
172	      return CustomSerDeUtils.DATA_SKETCH_THETA_SER_DE.serialize(((Union) value).getResult());
173	    } else if (value instanceof Sketch) {
174	      return CustomSerDeUtils.DATA_SKETCH_THETA_SER_DE.serialize(((Sketch) value));
175	    } else {
176	      throw new IllegalStateException(
177	          "Unsupported data type for Theta Sketch aggregation: " + value.getClass().getSimpleName());
178	    }
179	  }
180	
181	  @Override
182	  public Sketch deserializeAggregatedValue(byte[] bytes) {
183	    return CustomSerDeUtils.DATA_SKETCH_THETA_SER_DE.deserialize(bytes);
184	  }
185	}
