+import org.apache.datasketches.theta.*;
+public class T2 {
+  public static void main(String[] a) {
+    Union u = Union.builder().setNominalEntries(16384).buildUnion();
+    System.out.println("empty union getCurrentBytes=" + u.getCurrentBytes());
+    System.out.println("class=" + u.getClass());
+    // fill it
+    UpdateSketch s = Sketches.updateSketchBuilder().setNominalEntries(16384).build();
+    for (int i = 0; i < 100; i++) s.update(i);
+    Sketch compact = s.compact();
+    System.out.println("100-entry compact sketch bytes=" + compact.getCurrentBytes() + " serialized=" + compact.toByteArray().length);
+    u.union(compact);
+    System.out.println("union after 100 getCurrentBytes=" + u.getCurrentBytes());
+    System.out.println("union result bytes=" + u.getResult().getCurrentBytes());
+    System.out.println("getMaxUnionBytes(16384)=" + SetOperation.getMaxUnionBytes(16384));
+  }
+}
